/* eslint-disable no-undef */
import {
  Component,
  ComponentInterface,
  Element,
  Event,
  EventEmitter,
  forceUpdate,
  h,
  Host,
  Listen,
  Method,
  Prop,
  State,
  Watch,
} from '@stencil/core';

@Component({
  tag: 'groupui-tabs',
  styleUrl: 'tabs.scss',
  shadow: true,
})
export class Tabs implements ComponentInterface {
  /**
   * The id of the currently active tab.
   */
  @Prop({ reflect: true, mutable: true }) activeTabId: string;

  /**
   * Tabs should cover the whole width
   */
  @Prop({ reflect: true }) readonly fullWidth: boolean;

  /**
   * Tabs use spacing instead of padding
   */
  @Prop({ reflect: true }) readonly noPadding: boolean;

  /**
   * dispatched when tab change has finished  => 'event.detail' delivers the current and previous tab
   */
  @Event({ bubbles: false }) groupuiTabChange!: EventEmitter<{ tab: string; previousTab: string }>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @Element() host: HTMLElement;

  @State() activeTabPanel: HTMLElement;

  private titleObserver: MutationObserver;
  private activeTabPanelIndex: number = 0;
  private isSwitchingTabPanel = false;
  private previousTabPanel?: HTMLGroupuiTabElement;

  @Watch('activeTabId')
  watchActiveTabHandler(newActiveTabId: string, previousActiveTabId: string): void {
    if (newActiveTabId != null && newActiveTabId !== previousActiveTabId && !!previousActiveTabId) {
      this.selectActiveTab(newActiveTabId);
    }
  }

  @Listen('tabChanged')
  onTabChanged() {
    this.initActiveTabPanel();
    forceUpdate(this);
    this.setMutationsObserver();
  }

  componentWillLoad() {
    this.initActiveTabPanel();
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  disconnectedCallback() {
    this.titleObserver?.disconnect();
  }

  private setMutationsObserver() {
    if (this.titleObserver) {
      this.titleObserver.disconnect();
    } else {
      this.titleObserver = new MutationObserver(() => {
        forceUpdate(this);
      });
    }

    this.host.querySelectorAll('groupui-tab [slot="title"]').forEach((tab) => {
      this.titleObserver.observe(tab, {
        subtree: true,
        childList: true,
        characterData: true,
      });
    });
  }

  private initActiveTabPanel() {
    const tabs = this.getTabPanels();
    if (tabs.length === 0) return;
    const index = this.findIndexOfActiveTabOnStartup(tabs);
    this.setActiveTabPanel(index);
  }

  private findIndexOfActiveTabOnStartup(tabs: Array<HTMLGroupuiTabElement>): number {
    let index = this.activeTabPanelIndex;
    if (tabs.length > 0) {
      if (this.activeTabId) {
        index = tabs.findIndex((tab: HTMLGroupuiTabElement) => tab.tab === this.activeTabId);
      } else {
        index = tabs.findIndex((tab: HTMLGroupuiTabElement) => tab.active);
      }
    }
    return index < 0 ? this.activeTabPanelIndex : index;
  }

  private setActiveTabPanel(index: number) {
    this.activeTabPanel = this.getTabPanels()[index];
    (this.activeTabPanel as HTMLGroupuiTabElement).active = true;
    this.activeTabId = (this.activeTabPanel as HTMLGroupuiTabElement).tab;
    this.activeTabPanelIndex = index;
  }

  private getTabPanels(): Array<HTMLGroupuiTabElement> {
    // unfortunately, Stencil tests stop working if we simply query `this.host.querySelectorAll(':scope > groupui-tab')` here
    // see https://github.com/ionic-team/stencil/issues/2444
    const tabChildren = Array.from(this.host.querySelectorAll('groupui-tab'));
    return tabChildren.filter((tabElement) => tabElement.parentElement === this.host);
  }

  private getTabPanelsWithoutDisabled(): Array<HTMLGroupuiTabElement> {
    return this.getTabPanels().filter((tab: HTMLGroupuiTabElement) => !tab.disabled);
  }

  private getNextSelectableTabPanel(index: number): HTMLGroupuiTabElement {
    for (let i = index + 1; i < this.getTabPanels().length; i++) {
      if (!this.getTabPanels()[i].disabled) {
        return this.getTabPanels()[i];
      }
    }
    return this.getTabPanelsWithoutDisabled()[0];
  }

  private getPreviousSelectableTabPanel(index: number): HTMLGroupuiTabElement {
    for (let i = index - 1; i >= 0; i--) {
      if (!this.getTabPanels()[i].disabled) {
        return this.getTabPanels()[i];
      }
    }
    return this.getTabPanelsWithoutDisabled()[this.getTabPanelsWithoutDisabled().length - 1];
  }

  /**
   * Select a tab by the value of its `tab` property or an element reference.
   *
   * @param tab The tab instance to select. If passed a string, it should be the value of the tab's `tab` property.
   */
  @Method()
  async select(tab: string | HTMLElement): Promise<boolean> {
    return Promise.resolve(this.selectActiveTab(tab));
  }

  private selectActiveTab(tab: string | HTMLElement): boolean {
    if (this.isSwitchingTabPanel) {
      return false;
    }

    const selectedTabIndex = this.getTabPanelIndex(tab);

    if (selectedTabIndex === -1 || selectedTabIndex === this.activeTabPanelIndex) {
      return false;
    }

    this.switchTabPanel(selectedTabIndex);
    this.isSwitchingTabPanel = false;

    this.groupuiTabChange.emit({
      tab: (this.activeTabPanel as HTMLGroupuiTabElement).tab,
      previousTab: this.previousTabPanel?.tab,
    });

    return true;
  }

  private getTabPanelIndex(tabElement: string | HTMLElement): number {
    const tabs = this.getTabPanels();
    if (typeof tabElement === 'string') {
      return tabs.findIndex((tab) => tab.tab === tabElement);
    } else {
      return tabs.findIndex((tab) => tab === tabElement);
    }
  }

  private switchTabPanel(selectedTabPanelIndex: number) {
    if (this.isSwitchingTabPanel) {
      return;
    }
    this.isSwitchingTabPanel = true;

    this.handlePreviousTabPanel();
    this.setActiveTabPanel(selectedTabPanelIndex);
    this.setTabIndex(this.activeTabPanelIndex);
    this.setFocus(this.activeTabPanelIndex);
  }

  private handlePreviousTabPanel() {
    this.previousTabPanel = this.activeTabPanel as HTMLGroupuiTabElement;
    this.previousTabPanel.active = false;
  }

  /**
   * Get the currently selected tab.
   */
  @Method()
  async getSelected(): Promise<string | undefined> {
    return Promise.resolve(this.activeTabPanel ? (this.activeTabPanel as HTMLGroupuiTabElement).tab : undefined);
  }

  @Listen('keydown')
  onKeyDown(event: KeyboardEvent) {
    if (event.code === 'ArrowRight') {
      this.selectActiveTab(this.getNextSelectableTabPanel(this.activeTabPanelIndex));
    }
    if (event.code === 'ArrowLeft') {
      this.selectActiveTab(this.getPreviousSelectableTabPanel(this.activeTabPanelIndex));
    }
    if (event.code === 'Home') {
      event.preventDefault();
      this.selectFirstTabPanel();
    }
    if (event.code === 'End') {
      event.preventDefault();
      this.selectLastTabPanel();
    }
  }

  private selectFirstTabPanel() {
    this.selectActiveTab(this.getTabPanelsWithoutDisabled()[0]);
  }

  private selectLastTabPanel() {
    const tabPanels = this.getTabPanelsWithoutDisabled();
    this.selectActiveTab(tabPanels[tabPanels.length - 1]);
  }

  private setTabIndex(index: number) {
    const tabTitles = this.getTabTitles();
    tabTitles.forEach((tabTitle) => tabTitle.setAttribute('tabindex', '-1'));
    tabTitles[index].setAttribute('tabindex', '0');
  }

  private getTabTitles(): HTMLElement[] {
    return Array.from(this.host.shadowRoot.querySelectorAll('.title-content'));
  }

  private setFocus(index: number) {
    const tabTitles = this.getTabTitles();
    if (tabTitles[index].focus) {
      tabTitles[index].focus();
    }
  }

  private getTabBar() {
    const tabPanels = this.getTabPanels().map((tabPanel: HTMLGroupuiTabElement) => {
      // unfortunately, Stencil tests stop working if we simply query `tabPanel.querySelector(':scope > [slot="title"]')` here
      // see https://github.com/ionic-team/stencil/issues/2444
      const allChildTitleSlots = Array.from(tabPanel.querySelectorAll('[slot="title"]'));
      const directChildTitleSlot = allChildTitleSlots.find((slot) => slot.parentElement === tabPanel);
      const titleSlotContent = directChildTitleSlot?.innerHTML;
      return (
        <button
          key={tabPanel.tab}
          role="tab"
          aria-selected={tabPanel === this.activeTabPanel ? 'true' : 'false'}
          aria-disabled={tabPanel.disabled && 'true'}
          class={{
            active: tabPanel === this.activeTabPanel,
            disabled: tabPanel.disabled,
            'title-content': true,
          }}
          title={tabPanel.disabled && tabPanel.disabledDescription ? tabPanel.disabledDescription : undefined}
          // eslint-disable-next-line react/jsx-no-bind
          onClick={!tabPanel.disabled ? () => this.selectActiveTab(tabPanel.tab) : undefined}
          tabIndex={tabPanel === this.activeTabPanel ? 0 : -1}
          innerHTML={titleSlotContent}
        ></button>
      );
    });

    return (
      <div id="tab-bar" role="tablist">
        {tabPanels}
      </div>
    );
  }

  render() {
    return (
      <Host>
        {this.getTabBar()}
        <div id="content">
          <slot onSlotchange={() => this.onTabChanged()} />
        </div>
      </Host>
    );
  }
}
